import{_ as e,o as t,c as p,a0 as l}from"./chunks/framework.jwovEGr5.js";const d=JSON.parse('{"title":"생각을 바라보는 법","description":"","frontmatter":{},"headers":[],"relativePath":"inner-space/general/생각을-바라보는-법.md","filePath":"inner-space/general/생각을-바라보는-법.md"}'),o={name:"inner-space/general/생각을-바라보는-법.md"};function r(i,a,n,_,c,s){return t(),p("div",null,[...a[0]||(a[0]=[l('<h1 id="생각을-바라보는-법" tabindex="-1">생각을 바라보는 법 <a class="header-anchor" href="#생각을-바라보는-법" aria-label="Permalink to &quot;생각을 바라보는 법&quot;">​</a></h1><p>지난 몇 년간 생각에 휩쓸려서 살기 힘든 적이 많았다. 일어나지 않은 일을 미리 걱정하기도 하고, 다른 사람의 말과 표정, 말투까지 멋대로 해석해 판단하기도 했다. 작은 실수를 발견하면 그것을 내 개인의 문제로 치부하기도 했다.</p><p>이제까지 나는 머릿속에 떠오른 생각을 곧 현실이라 믿었다.</p><p>&#39;모든 일은 분명 잘못될 것이다.&#39; &#39;저 사람은 나를 싫어하는 게 분명하다.&#39; &#39;나는 왜 이것밖에 안 되지?&#39;</p><p>이런 문장들이 사실인지 확인도 하기 전에 이미 사실인 것처럼 반응했다. 생각이 불안을 만들고, 그 불안은 불안을 더 키웠다. 그렇게 불안정한 생각과 감정이 밀려오는 동안, 나는 아무것도 하지 못했다.</p><h2 id="일단-해야-할-일" tabindex="-1">일단 해야 할 일 <a class="header-anchor" href="#일단-해야-할-일" aria-label="Permalink to &quot;일단 해야 할 일&quot;">​</a></h2><p>상담 선생님은 먼저 불안정한 상황이 올 때 이런 방법을 알려주셨다. (감정 소모가 너무 심해서 진이 빠졌을 때도 유용!)</p><ol><li>일단 호흡하기. 4초 들이쉬고 - 4초 참고 - 4초 동안 내쉬기.</li><li>손가락으로 물건을 만지면서 감각 되살리기.</li><li>발끝으로 땅바닥 느끼기. 발가락도 꼼지락 거리기.</li><li>다시 호흡하기.</li></ol><h2 id="생각-나누기" tabindex="-1">생각 나누기 <a class="header-anchor" href="#생각-나누기" aria-label="Permalink to &quot;생각 나누기&quot;">​</a></h2><p>생각이 계속 마음에 남아 있다면, 그것을 문장으로 정리해본다. 그리고 정리한 문장을 다음과 같이 느낌, 판단, 사실로 나누어 본다.</p><p>여기서 느낌은 &quot;내 안에서 떠오른 생각&quot;, 판단은 &quot;외부에 대해 내가 떠올린 반응&quot;, 사실은 &quot;생각과 관련 없는 정말 일어난 사실&quot;을 뜻하는 것이다.</p><p>예를 들어 친구에게 메세지를 보냈는데, 오랫동안 답장이 오지 않았다고 해보자.</p><ul><li>느낌: 불안하다. 서운하다. 초조하다.</li><li>판단: 친구가 나를 싫어하게 된 것 같다.</li><li>사실: 어제 메세지를 보냈고, 아직 답장이 오지 않았다.</li></ul><p>처음에는 이 세 가지가 하나의 덩어리처럼 느껴진다.</p><blockquote><p>답장이 오지 않아서 불안하다. 분명 내가 싫어진 것이다.</p></blockquote><p>하지만 문장을 나누어 보면, 불안은 내가 실제로 경험하고 있는 느낌이고, 친구가 나를 싫어한다는 것은 아직 확인되지 않은 판단이다. 현재 확인할 수 있는 사실은 답장이 오지 않았다는 것뿐이다.</p><p>판단이 틀렸다는 뜻은 아니다. 실제로 그럴 가능성도 있다. 다만 가능성과 사실은 다르다. 내가 그렇게 느낀다는 것과 실제로 그렇다는 것도 다르다.</p><p>이 구분은 감정을 무시하기 위한 것이 아니다. 오히려 느낌을 느낌으로 인정하기 위한 것이다.</p><p>“친구가 나를 싫어한다”라고 말하면 확인되지 않은 판단이 사실처럼 굳어진다. 반면 “친구가 나를 싫어할까 봐 불안하다”라고 말하면, 내가 지금 무엇을 느끼고 무엇을 두려워하는지가 드러난다.</p><p>느낌은 반박할 필요가 없다. 불안하면 불안한 것이고, 서운하면 서운한 것이다. 다만 그 느낌이 곧바로 외부 세계에 관한 사실을 증명하지는 않는다.</p><h2 id="생각-바라보기" tabindex="-1">생각 바라보기 <a class="header-anchor" href="#생각-바라보기" aria-label="Permalink to &quot;생각 바라보기&quot;">​</a></h2><p>생각을 바라본다는 것은 생각을 없애는 것도, 생각을 외면하는 것도 아니다.</p><p>내 머릿속에 어떤 문장이 떠올랐을 때 그것과 하나가 되지 않고 거리를 두는 것이다. 만약 &#39;나는 쓸모없다&#39;라는 생각이 떠오른다면 이를 다음과 같이 바꾸어 말할 수 있다.</p><blockquote><p>나는 지금 &#39;나는 쓸모없다&#39;라는 생각을 하고 있다. 그 판단 때문에 불안감을 느끼고 있다. 지금 확인할 수 있는 사실은 없다. 판단하기는 이른 것이다!</p></blockquote><p>생각의 내용은 크게 달라지지 않았지만 적어도 그 생각으로 인한 불안은 줄일 수 있다. 전에는 생각 속에 서 있으며 휩싸였다면, 이제는 한 걸음 떨어져 생각을 바라보게 됐다.</p>',25)])])}const h=e(o,[["render",r]]);export{d as __pageData,h as default};
